   const char *ptr_image = header_data;
   for (size_t i = 0; i < image_height*image_width; i++) {
      uint8_t pixel[3];
      HEADER_PIXEL(ptr_image, pixel);
      image_input[i] = pixel[0];
   }

   //load second image
   // ptr_image = header_data2;
